/**
 * adb invocations of the Android device panel: the runner, the device list parser, PNG dimensions, and the argument
 * lists of device input.
 * Generated by ttoken/apply-brand.mjs from ttoken/device/src/adb.ts; edit it there.
 */

import { scrubbedParentEnv } from '@deepseek-ai/dsh-subprocess'
import { execa } from 'execa'
import { assertNever } from '@deepseek-ai/dsh-util-values'
import { resolveExecutable } from './platform-tools.ts'
import type { AndroidDevice, DeviceInput, DeviceKey } from './types.ts'

/** Output of one adb run that exited. */
export interface AdbOutput {
  /** Process exit code. */
  readonly exitCode: number
  /** Standard output bytes. */
  readonly stdout: Uint8Array
  /** Standard error, decoded as UTF-8. */
  readonly stderr: string
}

/**
 * Run adb with arguments and no shell on the Host.
 * @param args - adb arguments.
 * @param signal - cancellation of the run.
 * @returns the exited process's output.
 * @throws AdbUnavailableError when adb cannot start; AdbFailedError past the deadline or the output limit.
 */
export type AdbRunner = (args: readonly string[], signal: AbortSignal) => Promise<AdbOutput>

/** adb could not start, for example because it is not installed or not on PATH. */
export class AdbUnavailableError extends Error {
  override name = 'AdbUnavailableError'
}

/** adb ran past the deadline or wrote more than the output limit. */
export class AdbFailedError extends Error {
  override name = 'AdbFailedError'
}

/** Executables, deadline, and output limit of the runner. */
export interface AdbRunnerConfig {
  /** Tool name in messages, `adb` unless the runner starts another SDK tool. */
  readonly label?: string
  /** Executables to try in order until one starts: names or absolute Host paths. */
  readonly adbCommands: readonly string[]
  /** Deadline in milliseconds for one run. */
  readonly timeoutMs: number
  /** Most standard output bytes one run may write. */
  readonly maxOutputBytes: number
  /** Resolution of a candidate to an executable file; undefined skips the candidate. Defaults to the Host's PATH. */
  readonly resolve?: (command: string) => string | undefined
}

/**
 * Create the runner of one configuration. A run starts the executable that started last while it still exists;
 * otherwise it starts the first candidate that resolves to an executable file, so a tool installed after an earlier
 * run found none is used by the next run.
 * @param config - executables, deadline, and output limit.
 * @returns the runner.
 */
export function adbRunner(config: AdbRunnerConfig): AdbRunner {
  const tool = config.label ?? 'adb'
  const resolve = config.resolve ?? ((command: string) => resolveExecutable(command))
  let last: string | undefined
  const attempt = async (
    index: number, args: readonly string[], signal: AbortSignal, failure?: AdbUnavailableError,
  ): Promise<AdbOutput> => {
    const command = config.adbCommands[index]
    if (command === undefined) {
      throw failure ?? new AdbUnavailableError(`${tool} is not installed: none of ${config.adbCommands.join(', ')} exists`)
    }
    const executable = resolve(command)
    if (executable === undefined) return await attempt(index + 1, args, signal, failure)
    try {
      const output = await runOnce(config, executable, args, signal)
      last = executable
      return output
    } catch (error) {
      if (!(error instanceof AdbUnavailableError)) throw error
      return await attempt(index + 1, args, signal, failure ?? error)
    }
  }
  return async (args, signal) => {
    const known = last === undefined ? undefined : resolve(last)
    if (known !== undefined) {
      try {
        return await runOnce(config, known, args, signal)
      } catch (error) {
        if (!(error instanceof AdbUnavailableError)) throw error
      }
    }
    last = undefined
    return await attempt(0, args, signal)
  }
}

/** Run one adb executable. */
async function runOnce(config: AdbRunnerConfig, command: string, args: readonly string[], signal: AbortSignal): Promise<AdbOutput> {
  const result = await execa(command, args, {
    env: scrubbedParentEnv(),
    extendEnv: false,
    stdin: 'ignore',
    encoding: 'buffer',
    reject: false,
    timeout: config.timeoutMs,
    cancelSignal: signal,
    maxBuffer: config.maxOutputBytes,
  })
  const tool = config.label ?? 'adb'
  const shown = [tool, ...(args[0] === '-s' ? args.slice(2, 4) : args.slice(0, 2))].join(' ')
  if (result.isCanceled) throw signal.reason
  if (result.timedOut) throw new AdbFailedError(`${shown} timed out after ${config.timeoutMs}ms`)
  if (result.isMaxBuffer) throw new AdbFailedError(`${shown} wrote more than ${config.maxOutputBytes} bytes`)
  // A result without an exit code failed before the process ran; execa then always sets shortMessage.
  if (result.exitCode === undefined) throw new AdbUnavailableError(`${tool} could not start: ${String(result.shortMessage)}`)
  return { exitCode: result.exitCode, stdout: result.stdout, stderr: new TextDecoder().decode(result.stderr) }
}

/** AVD names: letters, digits, dots, underscores, and hyphens, not starting with a hyphen. */
const AVD_NAME = /^[\w.][\w.-]{0,99}$/

/**
 * Read the AVD names of `emulator -list-avds` output, skipping the log lines newer emulators print.
 * @param text - standard output.
 * @returns AVD names in the emulator's order.
 */
export function parseAvds(text: string): string[] {
  return text.split(/\r?\n/).map(line => line.trim()).filter(line => AVD_NAME.test(line))
}

/**
 * Check an AVD name before it reaches the emulator.
 * @param name - the name a caller sent.
 * @returns the problem, or null for a name an AVD can have.
 */
export function avdProblem(name: string): string | null {
  return AVD_NAME.test(name) ? null : 'The emulator name has characters AVD names do not use'
}

/** The header line of `adb devices`, after which each line names one device. */
const DEVICES_HEADER = 'List of devices attached'

/**
 * Read the devices of `adb devices -l` output. Lines before the header, such as daemon start notices, are skipped.
 * @param text - standard output.
 * @returns the listed devices in adb's order.
 */
export function parseDevices(text: string): AndroidDevice[] {
  const lines = text.split(/\r?\n/)
  const header = lines.findIndex(line => line.trim() === DEVICES_HEADER)
  return lines.slice(header + 1).flatMap((line): AndroidDevice[] => {
    const [serial, state, ...properties] = line.trim().split(/\s+/)
    if (serial === undefined || state === undefined || serial === '' || serial.startsWith('*')) return []
    const model = properties.find(property => property.startsWith('model:'))?.slice('model:'.length)
    return [{ serial, state, model: model === undefined || model === '' ? null : model.replaceAll('_', ' '), transport: transportOf(serial) }]
  })
}

/** How adb reaches a device, read from its serial. */
function transportOf(serial: string): AndroidDevice['transport'] {
  if (serial.startsWith('emulator-')) return 'emulator'
  if (serial.includes(':') || serial.includes('._adb-tls-connect.')) return 'network'
  return 'usb'
}

const PNG_SIGNATURE = [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a] as const

/**
 * Read a PNG image's dimensions from its header chunk.
 * @param png - the file bytes.
 * @returns width and height in pixels, or undefined when the bytes do not start a PNG image.
 */
export function pngSize(png: Uint8Array): { readonly width: number; readonly height: number } | undefined {
  if (png.byteLength < 24 || !PNG_SIGNATURE.every((byte, index) => png[index] === byte)) return undefined
  const view = new DataView(png.buffer, png.byteOffset, png.byteLength)
  const width = view.getUint32(16)
  const height = view.getUint32(20)
  return width > 0 && height > 0 ? { width, height } : undefined
}

/** adb serials: letters, digits, and the punctuation emulator, USB, and network serials use, not starting with a hyphen. */
const SERIAL = /^[\w.:@][\w.:@-]{0,199}$/
/** Largest coordinate accepted, past any phone or tablet screen. */
const MAX_COORDINATE = 100_000
/** Longest gesture accepted, in milliseconds. */
const MAX_SWIPE_MS = 10_000
/** Longest text one input types. */
const MAX_TEXT = 500
/** Text `input text` can type: printable ASCII. */
const TYPABLE = /^[\x20-\x7e]+$/

/**
 * Check a serial before it reaches adb.
 * @param serial - the serial a caller named.
 * @returns the problem, or null for a serial adb can take.
 */
export function serialProblem(serial: string): string | null {
  return SERIAL.test(serial) ? null : 'The device serial has characters adb serials do not use'
}

/**
 * Check one input before it reaches the device.
 * @param input - the input a caller sent.
 * @returns the problem, or null for an input the device can take.
 */
export function inputProblem(input: DeviceInput): string | null {
  switch (input.kind) {
    case 'tap':
      return coordinatesProblem([input.x, input.y])
    case 'swipe': {
      const problem = coordinatesProblem([input.fromX, input.fromY, input.toX, input.toY])
      if (problem !== null) return problem
      return Number.isSafeInteger(input.durationMs) && input.durationMs >= 0 && input.durationMs <= MAX_SWIPE_MS
        ? null : `A swipe lasts a whole number of milliseconds from 0 to ${MAX_SWIPE_MS}`
    }
    case 'text':
      if (input.text.length > MAX_TEXT) return `One input types at most ${MAX_TEXT} characters`
      return TYPABLE.test(input.text) ? null : 'adb types only printable ASCII letters, digits, spaces, and symbols'
    case 'key':
      return null
    default:
      return assertNever(input)
  }
}

/** Whether every coordinate is a whole pixel on a screen. */
function coordinatesProblem(values: readonly number[]): string | null {
  return values.every(value => Number.isSafeInteger(value) && value >= 0 && value <= MAX_COORDINATE)
    ? null : `Coordinates are whole pixels from 0 to ${MAX_COORDINATE}`
}

const KEY_CODES: Readonly<Record<DeviceKey, string>> = {
  back: 'KEYCODE_BACK',
  home: 'KEYCODE_HOME',
  recents: 'KEYCODE_APP_SWITCH',
  enter: 'KEYCODE_ENTER',
  delete: 'KEYCODE_DEL',
  power: 'KEYCODE_POWER',
}

/**
 * The adb arguments that send one checked input. `adb shell` joins its arguments into one command line for the
 * device's shell, so typed text is single-quoted for that shell, with spaces as the `%s` that `input text` reads.
 * @param input - an input {@link inputProblem} accepted.
 * @returns the arguments after `-s <serial>`.
 */
export function inputArgs(input: DeviceInput): string[] {
  switch (input.kind) {
    case 'tap':
      return ['shell', 'input', 'tap', String(input.x), String(input.y)]
    case 'swipe':
      return ['shell', 'input', 'swipe', String(input.fromX), String(input.fromY), String(input.toX), String(input.toY),
        String(input.durationMs)]
    case 'text':
      return ['shell', 'input', 'text', `'${input.text.replaceAll(' ', '%s').replaceAll('\'', '\'\\\'\'')}'`]
    case 'key':
      return ['shell', 'input', 'keyevent', KEY_CODES[input.key]]
    default:
      return assertNever(input)
  }
}

/**
 * A failed run's message: its standard error, else its standard output, else its exit code.
 * @param output - the exited run.
 * @returns one line for the user.
 */
export function failureText(output: AdbOutput): string {
  const text = output.stderr.trim() || new TextDecoder().decode(output.stdout).trim()
  return text === '' ? `adb exited with code ${output.exitCode}` : text.split(/\r?\n/)[0] ?? text
}
